// <PixelArt>: draws one of our own pixel-art motifs (M21 FR-F3, TR-4, ADR 0009). The motifs are typed
// modules generated by scripts/art/import.mjs; the first-screen ones (core.ts) ship in the main chunk,
// every other group is a lazy chunk that loads the first time one of its motifs is drawn. No inline
// style reaches the DOM (CSP `style-src 'self'`): fills are `.pxs-<slot>` classes, frames are CSS
// steps() keyframes, and reduced motion pins frame 1 (art.css).
import { type JSX, useEffect, useSyncExternalStore } from 'react';
import './art.css';
import { motifs as coreMotifs } from './core';
import type { ArtGroup, Motif } from './motif';
import { type ArtName, gridOf, groupOf } from './names';

export type { Motif } from './motif';
export type { ArtName } from './names';

export type Ramp =
  | 'blob'
  | 'bronze'
  | 'silver'
  | 'gold'
  | 'plat'
  | 'ruby'
  | 'majestic'
  | 'wood'
  | 'stone'
  | 'leaf'
  | 'fire';
export type Cauldron = 'power' | 'quicc' | 'high-iq' | 'kazam';

export interface PixelArtProps {
  name: ArtName;
  /** A whole multiple of the motif's own grid: a 16-grid motif at 1..4 is 16, 32, 48 or 64 px. */
  scale?: 1 | 2 | 3 | 4;
  ramp?: Ramp;
  /** World tint (`--px-world`), for a frame or badge around the motif. */
  w?: 1 | 2 | 3 | 4 | 5 | 6 | 7;
  /** An alchemy cauldron's colour (owner addition): pot and rim in its bubble group's colour. */
  cauldron?: Cauldron;
  /** Overrides the motif's own title (the accessible name). */
  title?: string;
  /** Beside its word: hidden from assistive tech. */
  decorative?: boolean;
  /** Loop the frames (default true). Celebrations play once; reduced motion always pins a frame. */
  animate?: boolean;
  className?: string;
}

const registry = new Map<string, Motif>(Object.entries(coreMotifs));
let version = 0;
const listeners = new Set<() => void>();
const subscribe = (fn: () => void) => {
  listeners.add(fn);
  return () => {
    listeners.delete(fn);
  };
};
const getVersion = () => version;

/** Adds motifs (a lazy group registers itself through this). */
export function registerArt(motifs: Record<string, Motif>): void {
  let added = false;
  for (const [id, m] of Object.entries(motifs))
    if (!registry.has(id)) {
      registry.set(id, m);
      added = true;
    }
  if (added) {
    version++;
    for (const fn of listeners) fn();
  }
}

export const hasArt = (name: string): boolean => registry.has(name);

type LazyGroup = Exclude<ArtGroup, 'ui'>;
const GROUPS: Record<LazyGroup, () => Promise<{ motifs: Record<string, Motif> }>> = {
  now: () => import('./generated/now'),
  cards: () => import('./generated/cards'),
  flows: () => import('./generated/flows'),
  character: () => import('./generated/character'),
  map: () => import('./generated/map'),
  systems: () => import('./generated/systems'),
  time: () => import('./generated/time'),
};
const inflight = new Map<string, Promise<void>>();

/**
 * Loads one lazy group's motifs (one request per group; a failure leaves placeholders and may be retried
 * later). `<PixelArt>` calls this itself; call it directly only to prefetch.
 */
export function loadArtGroup(group: ArtGroup | 'core'): Promise<void> {
  if (group === 'core' || group === 'ui') return Promise.resolve();
  const existing = inflight.get(group);
  if (existing) return existing;
  const load = (GROUPS as Partial<Record<string, (typeof GROUPS)[LazyGroup]>>)[group];
  if (!load) return Promise.resolve(); // a name in no group: it stays a placeholder
  const p = load()
    .then((mod) => registerArt(mod.motifs))
    .catch(() => {
      inflight.delete(group);
    });
  inflight.set(group, p);
  return p;
}

export function PixelArt({
  name,
  scale = 1,
  ramp,
  w,
  cauldron,
  title,
  decorative = false,
  animate = true,
  className,
}: PixelArtProps): JSX.Element {
  useSyncExternalStore(subscribe, getVersion, getVersion);
  const motif = registry.get(name);
  useEffect(() => {
    if (motif) return;
    void loadArtGroup(groupOf(name));
  }, [motif, name]);

  const [gw, gh] = motif?.grid ?? gridOf(name);
  const width = gw * scale;
  const height = gh * scale;
  const n = motif?.frames.length ?? 0;
  const classes = [
    'px-art',
    `px-${name}`,
    n > 1 ? `px-n${n} px-fps${motif?.fps}` : '',
    n > 1 && animate ? 'px-anim' : '',
    motif?.once ? 'px-once' : '',
    ramp ? `px-ramp-${ramp}` : '',
    w ? `px-w${w}` : '',
    cauldron ? `px-cauldron-${cauldron}` : '',
    motif ? '' : 'px-missing',
    className ?? '',
  ]
    .filter(Boolean)
    .join(' ');
  const label = title ?? motif?.title ?? name;
  return (
    // biome-ignore lint/a11y/noSvgWithoutTitle: the title is rendered below unless the art is decorative (then aria-hidden)
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={`0 0 ${gw} ${gh}`}
      width={width}
      height={height}
      shapeRendering="crispEdges"
      className={classes}
      focusable="false"
      {...(decorative || !motif ? { 'aria-hidden': true } : { role: 'img', 'aria-label': label })}
    >
      {!decorative && motif ? <title>{label}</title> : null}
      {motif?.frames.map((frame, i) => (
        <g
          // biome-ignore lint/suspicious/noArrayIndexKey: frames are a fixed, ordered list
          key={i}
          className={`px-f px-f${i}${i === n - 1 ? ' px-flast' : ''}`}
        >
          {Object.entries(frame).map(([slot, d]) => (
            <path key={slot} className={`pxs-${slot}`} d={d} />
          ))}
        </g>
      ))}
    </svg>
  );
}
